import subprocess
# Use pdftotext to find where References section starts
result = subprocess.run(['pdftotext', '-layout', 'main.pdf', '-'], capture_output=True, text=True)
lines = result.stdout.split('\n')
for i, line in enumerate(lines):
    if 'References' in line and i > 50:
        print(f'Line {i}: {line.strip()}')
    if 'Limitations' in line:
        print(f'Line {i}: {line.strip()}')
    if '\\x0c' in line or '\f' in line:
        print(f'--- PAGE BREAK near line {i} ---')
" 2>&1

python3 -c "
import subprocess
result = subprocess.run(['pdftotext', '-layout', 'main.pdf', '-'], capture_output=True, text=True)
pages = result.stdout.split('\f')
for i, page in enumerate(pages):
    if 'Limitation' in page:
        # Find the line
        for line in page.split('\n'):
            if 'Limitation' in line:
                print(f'Page {i+1}: {line.strip()[:100]}')
    if 'Conclusion' in page:
        for line in page.split('\n'):
            if 'Conclusion' in line and 'Table' not in line:
                print(f'Page {i+1}: {line.strip()[:100]}')
    if 'References' in page and i > 5:
        for line in page.split('\n'):
            if line.strip().startswith('References') or '  References' in line:
                print(f'Page {i+1}: {line.strip()[:100]}')
" 2>&1
